corrected_code:
const { Queue } = require('bullmq');
const campaignQueue = new Queue('marketing-campaigns', { connection: redisConn });

app.post('/api/campaigns/jobs/:jobId/retry', requireSession, async (req, res) => {
  const job = await campaignQueue.getJob(req.params.jobId);
  if (!job) return res.status(404).json({ error: 'Campaign job not found' });
  if (job.data.tenantId !== req.user.tenantId) {
    return res.status(403).json({ error: 'Forbidden: campaign job belongs to another organization' });
  }
  await job.retry();
  res.json({ success: true, retriedJobId: job.id });
});
